create table cicd.demo (
    id                number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1
    cache 20 noorder nocycle nokeep noscale not null enable,
    name              varchar2(400 char),
    location          varchar2(300 byte),
    ci_cd_test_column varchar2(100 byte),
    email             varchar2(100 byte) not null enable
);

alter table cicd.demo
    add constraint demo_pk primary key ( id )
        using index enable;


